import React, { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000/api";

function AdminPanel({
  candidateForm,
  setCandidateForm,
  onSave,
  editId,
  setEditId,
  onDelete,
  candidates,
  theme,
}) {
  const [codes, setCodes] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");

  const [stats, setStats] = useState({
    totalVoterCodes: 0,
    usedCodes: 0,
    totalVotes: 0,
    turnout: 0,
  });

  const token = localStorage.getItem("token");

  const authHeader = {
    headers: { Authorization: `Bearer ${token}` },
  };

  const positions = [
    "President",
    "Vice President",
    "Secretary",
    "Treasurer",
    "Auditor",
    "Business Manager",
  ];

  const yearLevels = ["1st Year", "2nd Year", "3rd Year", "4th Year"];
  const blocks = ["Block 1", "Block 2", "Block 3"];
  const courses = ["BSIT", "BPA", "BSCS", "BSENTREP", "BTVTED"];

  // ================= FETCH =================
  const fetchCodes = async () => {
    try {
      const res = await axios.get(`${API_URL}/codes`, authHeader);
      setCodes(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchStats = async () => {
    try {
      const res = await axios.get(`${API_URL}/stats`, authHeader);
      setStats(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const refreshAll = async () => {
    await Promise.all([fetchCodes(), fetchStats()]);
  };

  useEffect(() => {
    refreshAll();
  }, []);

  // ================= ACTIONS =================
  const generateCodes = async () => {
    const amount = prompt("How many codes?");
    if (!amount) return;

    try {
      await axios.post(
        `${API_URL}/codes/generate`,
        { amount: Number(amount) },
        authHeader
      );
      refreshAll();
    } catch (err) {
      console.error(err);
    }
  };

  const deleteCode = async (id) => {
    try {
      await axios.delete(`${API_URL}/codes/${id}`, authHeader);
      refreshAll();
    } catch (err) {
      console.error(err);
    }
  };

  const resetElection = async () => {
    if (!window.confirm("Reset election?")) return;

    try {
      await axios.post(
        `${API_URL}/admin/reset-election`,
        {},
        authHeader
      );
      refreshAll();
    } catch (err) {
      console.error(err);
    }
  };

  // ================= FORM =================
  const handleCancelEdit = () => {
    setCandidateForm({
      firstName: "",
      lastName: "",
      candidacy: "",
      partylist: "",
      yearLevel: "",
      block: "",
      course: "",
      description: "",
      image: null,
    });
    setEditId(null);
  };

  const handleEditClick = (c) => {
    setEditId(c._id);
    setCandidateForm({
      firstName: c.firstName,
      lastName: c.lastName,
      candidacy: c.candidacy,
      partylist: c.partylist,
      yearLevel: c.yearLevel,
      block: c.block,
      course: c.course,
      description: c.description,
      image: null,
    });
  };

  const filteredCandidates = candidates.filter(
    (c) => !selectedCourse || c.course === selectedCourse
  );

  // ================= UI =================
  return (
    <div style={containerStyle(theme)}>
      
      {/* ================= STATS ================= */}
      <h3>Election Statistics</h3>

      <div style={statsContainer}>
        <StatCard title="Total Codes" value={stats.totalVoterCodes} />
        <StatCard title="Used Codes" value={stats.usedCodes} />
        <StatCard title="Total Votes Cast" value={stats.totalVotes} />
        <StatCard title="Turnout" value={`${stats.turnout}%`} />
      </div>

      <button style={resetButton} onClick={resetElection}>
        Reset Election
      </button>

      {/* ================= FORM ================= */}
      <h3>{editId ? "Edit Candidate" : "Add Candidate"}</h3>

      <form style={formStyle} onSubmit={(e) => { e.preventDefault(); onSave(); }}>
        <input
          placeholder="First Name"
          value={candidateForm.firstName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, firstName: e.target.value })
          }
          style={inputStyle}
        />

        <input
          placeholder="Last Name"
          value={candidateForm.lastName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, lastName: e.target.value })
          }
          style={inputStyle}
        />

        <select
          value={candidateForm.candidacy}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, candidacy: e.target.value })
          }
          style={inputStyle}
        >
          <option value="">Select Position</option>
          {positions.map((p) => (
            <option key={p}>{p}</option>
          ))}
        </select>

        <select
          value={candidateForm.course}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, course: e.target.value })
          }
          style={inputStyle}
        >
          <option value="">Course</option>
          {courses.map((c) => (
            <option key={c}>{c}</option>
          ))}
        </select>

        <textarea
          placeholder="Description"
          value={candidateForm.description}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, description: e.target.value })
          }
          style={inputStyle}
        />

        <button type="submit" style={primaryButton}>
          {editId ? "Save" : "Add"}
        </button>

        {editId && (
          <button type="button" onClick={handleCancelEdit} style={cancelButton}>
            Cancel
          </button>
        )}
      </form>

      {/* ================= CANDIDATES ================= */}
      <h3>Candidates</h3>

      {filteredCandidates.map((c) => (
        <div key={c._id} style={candidateCard}>
          <div>
            {c.firstName} {c.lastName} - {c.candidacy}
          </div>

          <div>
            <button onClick={() => handleEditClick(c)} style={editButton}>
              Edit
            </button>

            <button onClick={() => onDelete(c._id)} style={deleteButton}>
              Delete
            </button>
          </div>
        </div>
      ))}

      {/* ================= CODES ================= */}
      <h3>Voter Codes</h3>

      <button onClick={generateCodes} style={generateButton}>
        Generate Codes
      </button>

      <table style={table}>
        <thead>
          <tr>
            <th style={tableCell}>Code</th>
            <th style={tableCell}>Status</th>
            <th style={tableCell}>Action</th>
          </tr>
        </thead>

        <tbody>
          {codes.map((c) => (
            <tr key={c._id}>
              <td style={tableCell}>{c.code}</td>
              <td style={tableCell}>{c.used ? "Used" : "Unused"}</td>
              <td style={tableCell}>
                <button onClick={() => deleteCode(c._id)} style={deleteButton}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/* ================= COMPONENT ================= */
const StatCard = ({ title, value }) => (
  <div style={statCard}>
    <h4>{title}</h4>
    <p>{value}</p>
  </div>
);

/* ================= STYLES ================= */
const containerStyle = (theme) => ({
  padding: 20,
  background: theme.card,
});

const statsContainer = {
  display: "flex",
  gap: 10,
};

const statCard = {
  padding: 10,
  background: "#eee",
  borderRadius: 6,
};

const formStyle = {
  display: "flex",
  flexDirection: "column",
  gap: 10,
};

const inputStyle = {
  padding: 8,
};

const candidateCard = {
  display: "flex",
  justifyContent: "space-between",
  padding: 10,
  border: "1px solid #ccc",
};

const primaryButton = {
  background: "blue",
  color: "white",
  padding: 8,
};

const cancelButton = {
  background: "red",
  color: "white",
  padding: 8,
};

const editButton = {
  background: "orange",
  color: "white",
};

const deleteButton = {
  background: "red",
  color: "white",
};

const generateButton = {
  background: "green",
  color: "white",
  padding: 8,
};

const resetButton = {
  background: "black",
  color: "white",
  padding: 8,
};

const table = {
  width: "100%",
  marginTop: 10,
};

const tableCell = {
  border: "1px solid #ccc",
  padding: 6,
};

export default AdminPanel;
